INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 19, 'theory', 'Quiz: CSS Flexbox');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 0, 'Which property sets the direction of a flex container''s main axis?', '["align-items", "flex-direction", "justify-content", "flex-wrap"]', 1, 'flex-direction chooses the direction of the main axis: row, row-reverse, column or column-reverse. justify-content and align-items only align items along the main and cross axes, and flex-wrap allows lines to wrap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 1, 'A 600px container with three items, each with flex-basis 100px and flex-grow: 1. How wide does each item become?', '["100px: the basis doesn''t change", "300px", "600px", "200px"]', 3, '300px is taken and 300px is free. Three equal shares give 100px each, so each item grows from 100px to 200px. Growth is counted from the basis, not from zero.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 2, 'How does the flex: 1 shorthand differ from flex: auto?', '["flex: 1 has a basis of zero, flex: auto has the content size", "flex: 1 forbids shrinking, flex: auto allows it", "flex: 1 turns on line wrapping", "No difference, they are synonyms"]', 0, 'flex: 1 expands to 1 1 0%: space is divided strictly by shares. flex: auto is 1 1 auto: the item first gets its content size, then shares what is left. That is why with flex: auto column widths can differ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 3, 'A long word in a flex item sticks out past the container. What fixes it?', '["align-items: stretch", "justify-content: space-between", "min-width: 0 on the item (plus overflow and text-overflow if the text must be truncated)", "order: -1"]', 2, 'The default minimum width of a flex item equals the width of its content, so it won''t shrink below the long word. min-width: 0 removes that limit; to truncate with an ellipsis, add hidden overflow, text-overflow and white-space: nowrap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 19, 4, 'Why shouldn''t you use the order property to change the meaningful order of content?', '["It doesn''t work in mobile browsers", "Keyboard focus and screen readers follow the markup order, so the picture diverges from what the user hears and operates", "It turns off flex-grow on the neighbors", "It changes the order of elements in the DOM and scripts break"]', 1, 'order changes only the display. Tab navigation and screen readers read the markup, so focus will jump around the page at random. The markup order must make sense, and order and row-reverse are only for cosmetics.');
